var unrelated=procedure with{Nodes=[..procedure.Nodes,N("unrelated","missing.module")],Configuration=new(){Inputs=[new("unbound","unbound",DataKind.Integer)],Subscriptions=[new("unrelated","value",false,new(WorkflowSourceKind.WorkflowInput,"unbound"))]}};
Check((await debug.RunAsync(unrelated,"source",".",new Dictionary<string,JsonElement>())).Status==NodeRunStatus.Success,"unrelated missing module and workflow input do not block source self-run");
var argumentFlow=new ProcedureDocument("args","args",[N("target",work.Id)],[],[]){Configuration=new(){Inputs=[new("arg-id","arg",DataKind.Integer)],Subscriptions=[new("target","value",false,new(WorkflowSourceKind.WorkflowInput,"arg-id"))]}};var arguments=new Dictionary<string,PortValue>{{"arg",PortValue.Integer(10)}};var argumentRun=await new GraphExecutor(registry).RunAsync(argumentFlow,".",inputs:arguments);arguments["arg"]=PortValue.Integer(999);Check(argumentRun.WorkflowInputs["arg"].As<long>()==10,"execution session preserves immutable actual workflow invocation input");var debugArgument=await debug.RunAsync(argumentFlow,"target",".",new Dictionary<string,JsonElement>{{"add",JsonSerializer.SerializeToElement(5)}},argumentRun.Nodes,argumentRun.WorkflowInputs);Check(debugArgument.Outputs["value"].As<long>()==15,"internal Group-style module debug can reuse actual invocation inputs");
var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var cleanupDone=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
await using(var session=new ToolDebugSession(async(v,token)=>{entered.TrySetResult();try{await Task.Delay(Timeout.Infinite,token);return single;}finally{await release.Task;cleanupDone.TrySetResult();}},0)){
 var run=session.RunOnceAsync(values);await entered.Task;Check(session.State==ToolDebugState.RunningOnce&&session.IsBusy,"session reports running single-module state");await Reject(()=>session.RunOnceAsync(values),"concurrent self-run rejected");var stop=session.StopAsync();await Task.Delay(15);Check(!stop.IsCompleted&&session.State==ToolDebugState.Stopping,"stop waits for actual cleanup rather than only cancelling token");release.TrySetResult();await stop;try{await run;}catch(OperationCanceledException){}Check(cleanupDone.Task.IsCompleted&&session.State==ToolDebugState.Idle&&!session.IsBusy,"stop drains active execution and returns idle");}
var observed=new List<long>();await using(var snapshotSession=new ToolDebugSession(async(v,t)=>{await Task.Yield();observed.Add(v["add"].GetInt64());return single;},0)){var run=snapshotSession.RunOnceAsync(values);values["add"]=JsonSerializer.SerializeToElement(99);await run;Check(observed.Single()==5,"run parameters are snapshotted before caller mutation");}
int looping=0,maxParallel=0,concurrent=0;using var loopCancel=new CancellationTokenSource();await using(var repeating=new ToolDebugSession(async(v,t)=>{int active=Interlocked.Increment(ref concurrent);maxParallel=Math.Max(maxParallel,active);try{await Task.Delay(3,t);return single;}finally{Interlocked.Decrement(ref concurrent);}},1)){
 var run=repeating.RunContinuousAsync(()=>values,r=>{if(++looping==3)loopCancel.Cancel();},loopCancel.Token);try{await run;}catch(OperationCanceledException){}Check(looping==3&&maxParallel==1&&repeating.State==ToolDebugState.Idle,"continuous execution waits for each result and cancels without overlapping rounds");}
var failedRounds=0;await using(var failedSession=new ToolDebugSession((v,t)=>Task.FromResult(single with{Status=NodeRunStatus.Failed,Outputs=new Dictionary<string,PortValue>()}),0)){await failedSession.RunContinuousAsync(()=>values,_=>failedRounds++);Check(failedRounds==1&&!failedSession.IsBusy,"independent safety policy stops continuous run on failed record");}
var closeStarted=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var closingSession=new ToolDebugSession(async(v,t)=>{closeStarted.TrySetResult();try{await Task.Delay(Timeout.Infinite,t);return single;}finally{Interlocked.Increment(ref disposed);}},0);var closingRun=closingSession.RunOnceAsync(values);await closeStarted.Task;await closingSession.DisposeAsync();try{await closingRun;}catch(OperationCanceledException){}Check(disposed==1&&closingSession.State==ToolDebugState.Disposed&&!closingSession.IsBusy,"dispose cancels and waits for execution finally cleanup");await Reject(()=>closingSession.RunOnceAsync(values),"closed session cannot restart");await closingSession.DisposeAsync();Check(disposed==1,"dispose is idempotent");
