int previewCount=upstream+target+downstream;Check(debug.ResolveInput(procedure,"target","value",full.Nodes).As<long>()==10,"preview resolves the exact connection without execution");Check(debug.ResolveInput(subscribed,"target","value",full.Nodes).As<long>()==10,"preview resolves target subscription");Check(debug.ResolveInput(argumentFlow,"target","value",workflowInputs:argumentRun.WorkflowInputs).As<long>()==10,"preview resolves scoped workflow input snapshot");await Reject(()=>{debug.ResolveInput(procedure,"target","value",badCache);return Task.CompletedTask;},"preview rejects failed cached producer");await Reject(()=>{debug.ResolveInput(procedure,"target","value",wrongCache);return Task.CompletedTask;},"preview rejects incompatible image/input cardinality");await Reject(()=>{debug.ResolveInput(procedure with{Configuration=new(){Subscriptions=[new("target","value",false,new(WorkflowSourceKind.NodeOutput,"source","value"))]}},"target","value",full.Nodes);return Task.CompletedTask;},"preview rejects duplicate connection and subscription instead of guessing source");Check(previewCount==upstream+target+downstream,"preview reads never execute any module");
var dir=Path.GetFullPath("analysis/full-audit/debug-session-runtime");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"results.json"),JsonSerializer.Serialize(new{passed=true,count=passed.Count,passedChecks=passed,scope="independent debug runtime/session; native upstream-preparation boundary remains unknown"},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"PASS {passed.Count} debug runtime checks; isolated target result15; stop/close await cleanup.");
sealed class Functional(ModuleDescriptor descriptor,Func<ModuleExecutionContext,ModuleResult> run):IModule{public ModuleDescriptor Descriptor=>descriptor;public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext context,CancellationToken token)=>ValueTask.FromResult(run(context));}
sealed class Slow(ModuleDescriptor descriptor,Action closed):IModule,IAsyncDisposable{public ModuleDescriptor Descriptor=>descriptor;public async ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext context,CancellationToken token){await Task.Delay(Timeout.Infinite,token);return new(ModuleStatus.Success,new Dictionary<string,PortValue>());}public ValueTask DisposeAsync(){closed();return ValueTask.CompletedTask;}}
